from format_lecon import table,paras
DIAGNOSTICS=[
('Ésotropie accommodative','L’hypermétropie favorise la convergence liée à l’accommodation.','L’angle diminue sous correction optique complète.','La réfraction sous cycloplégie et les mesures avec lunettes caractérisent la composante accommodative.','Prescrire la correction adaptée et traiter l’amblyopie.','Le risque visuel impose un suivi précoce.'),
('Exotropie intermittente','La fusion contrôle inconstamment la déviation vers l’extérieur.','La déviation apparaît avec la fatigue ou en fixation lointaine.','Le bilan orthoptique mesure angle, contrôle et stéréoscopie.','Corriger la réfraction et surveiller le contrôle ; discuter la chirurgie si dégradation.','La baisse de vision impose de rechercher une cause sensorielle.'),
('Ésotropie infantile','Une désorganisation précoce de la vision binoculaire accompagne une convergence constante.','La déviation est installée avant six mois.','L’examen confirme la déviation, la réfraction et l’intégrité oculaire.','Traiter l’amblyopie et planifier précocement l’alignement avec le spécialiste.','Une limitation véritable ou une leucocorie impose un autre bilan.'),
('Paralysie du nerf abducens (VI)','La faiblesse du droit latéral limite l’abduction.','La diplopie horizontale augmente dans le regard du côté atteint.','Le déficit d’abduction et le bilan étiologique distinguent nerf, orbite et restriction.','Évaluer rapidement une forme acquise et rechercher hypertension intracrânienne ou lésion neurologique.','🚩 E2 si récente, surtout chez l’enfant ; E1 si signes neurologiques aigus.'),
('Paralysie du nerf trochléaire (IV)','La faiblesse de l’oblique supérieur provoque un désalignement vertical et torsionnel.','La gêne augmente notamment en regard inférieur.','La motilité, la torsion et l’inclinaison de tête orientent ; un signe isolé ne suffit pas.','Rechercher une cause acquise et soulager la diplopie après le tri.','🚩 E2 si récente ; E1 si traumatisme grave ou signes centraux.'),
('Paralysie du nerf oculomoteur (III)','Plusieurs muscles, la paupière et parfois la pupille perdent leur commande.','Le ptosis peut masquer la diplopie ; la mydriase accroît l’alarme.','Une imagerie vasculaire urgente recherche une compression anévrismale.','Adresser en urgence toute paralysie acquise ; ne pas rassurer sur la seule pupille.','🚩 E1 : un anévrisme doit être exclu sans attendre.'),
('Myasthénie oculaire','La transmission neuromusculaire devient défaillante et fatigable.','Le ptosis et la diplopie fluctuent sans atteinte pupillaire habituelle.','Les anticorps et l’électrophysiologie étayent une clinique compatible.','Rechercher immédiatement une extension bulbaire ou respiratoire.','🚩 E1 si dysphagie, dysarthrie ou faiblesse respiratoire.'),
('Orbitopathie dysthyroïdienne','L’inflammation puis la fibrose orbitaires restreignent les mouvements.','La rétraction palpébrale, l’exophtalmie et la restriction orientent.','L’examen visuel, le bilan thyroïdien et l’imagerie ciblée déterminent la gravité.','Protéger la surface oculaire et organiser la prise en charge conjointe.','🚩 E1 si neuropathie optique ou lésion cornéenne menaçante.'),
('Syndrome de Duane','Une dysinnervation congénitale perturbe les mouvements horizontaux.','Le globe se rétracte et la fente palpébrale se rétrécit lors de certains mouvements.','L’examen orthoptique retrouve un profil ancien avec rétraction.','Surveiller vision et posture ; discuter une chirurgie fonctionnelle sélectionnée.','Une apparition réellement nouvelle ne doit pas être attribuée à ce syndrome congénital.'),
('Rétinoblastome','Une tumeur rétinienne altère l’entrée visuelle et peut provoquer une déviation sensorielle.','Une leucocorie ou un reflet rouge anormal alerte.','Le fond d’œil spécialisé et l’imagerie oculaire confirment la suspicion.','Adresser immédiatement à l’ophtalmologie pédiatrique et au centre expert.','🚩 E1 : le pronostic vital prime sur l’alignement.')]
def comparison():
 return paras('Les numéros organisent dix hypothèses utiles ; ils ne représentent pas un classement de prévalence démontré. Les sources consultées ne comparent pas ces dix entités dans une même population suisse. Les formes infantiles et les causes acquises ne partagent pas le même dénominateur.', 'E1 signifie une menace à évaluer immédiatement ; E2 impose une évaluation rapide adaptée au contexte. Ces repères pédagogiques ne sont pas un score validé. Les urgences restent en tête de la conduite, quel que soit le numéro du diagnostic.')+table(['Diagnostic','Mécanisme','Signe discriminant','Examen qui oriente ou tranche','Conduite','Priorité'],[[f'DX.{i} — '+r[0],*r[1:]] for i,r in enumerate(DIAGNOSTICS,1)])
